function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least 1 node.';
  let slots = 1;
  for (let i = 0; i < root.length; i++) {
    if (i >= slots) return 'The list has entries after the last possible child.';
    if (root[i] !== null) slots += 2;
  }
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Every node value is an integer from 0 to 100000.';
  return null;
}

