function maximumAverageSubtree(root) {
  let best = 0;

  const visit = (node) => {
    if (node === null) {
      return [0, 0];
    }
    const [leftSum, leftCount] = visit(node.left);
    const [rightSum, rightCount] = visit(node.right);
    const sum = leftSum + rightSum + node.val;
    const count = leftCount + rightCount + 1;
    best = Math.max(best, sum / count);
    return [sum, count];
  };

  visit(root);
  return best;
}

