function maximumAverageSubtree(root) {
  // Collect every node, then add up each node's subtree separately with its own walk.
  const all = [];
  const pending = [root];
  while (pending.length) {
    const node = pending.pop();
    if (!node) continue;
    all.push(node);
    pending.push(node.left, node.right);
  }
  let answer = -1;
  for (const top of all) {
    let total = 0;
    let size = 0;
    const walk = [top];
    while (walk.length) {
      const node = walk.pop();
      if (!node) continue;
      total += node.val;
      size += 1;
      walk.push(node.left, node.right);
    }
    if (total / size > answer) answer = total / size;
  }
  return answer;
}

